import PageShell from "../../components/PageShell.jsx";

const projects = [
  ["01", "Business websites", "Clear, responsive digital homes for growing teams."],
  ["02", "Online stores", "Thoughtful product journeys that make selling simpler."],
  ["03", "Custom software", "Useful tools designed around real business workflows."],
];

export default function PortfolioPage() {
  return (
    <PageShell>
      <section className="section-pad" aria-labelledby="portfolio-heading">
        <p className="section-label">SELECTED WORK</p>
        <h1 id="portfolio-heading">Ideas made<br /><em>useful.</em></h1>
        <div className="package-grid">
          {projects.map(([number, title, description]) => <article className="package-card" key={number}><p className="section-label">{number}</p><h2>{title}</h2><p className="package-desc">{description}</p><a className="package-cta" href="/contact">Discuss a similar project</a></article>)}
        </div>
      </section>
    </PageShell>
  );
}